def parse_log_file(log_file_path, threshold):
    ip_counts = {}
    with open(log_file_path, 'r') as log_file:
        for line in log_file:
            ip_address = line.split()[0]
            ip_counts[ip_address] = ip_counts.get(ip_address, 0) + 1

    frequent_ips = [ip for ip, count in ip_counts.items() if count > threshold]
    frequent_ips.sort()
    return frequent_ips

