def find_affordable_vacations(vacation_options, total_budget):
    affordable_destinations = []
    for option in vacation_options:
        destination = option["destination"]
        cost_per_day = option["cost_per_day"]
        days = option["days"]
        total_cost = cost_per_day * days
        if total_cost <= total_budget:
            affordable_destinations.append(destination)
    return affordable_destinations

def calculate_treatment_costs(treatments):
    total_costs = {}
    for animal, treatments_list in treatments.items():
        total_cost = 0
        for treatment, cost in treatments_list:
            total_cost += cost
        total_costs[animal] = total_cost
    return total_costs

def analyze_sentiment(posts):
    positive_words = ["good", "great", "excellent", "happy"]
    negative_words = ["bad", "terrible", "worst", "sad"]

    sentiment_counts = {
        "positive": 0,
        "negative": 0,
        "neutral": 0
    }

    for post in posts:
        post = post.lower().replace(",", "").replace(".", "").replace("!", "").replace("?", "")
        words = post.split()

        positive_count = sum(word in positive_words for word in words)
        negative_count = sum(word in negative_words for word in words)

        if positive_count > 0 and negative_count == 0:
            sentiment_counts["positive"] += 1
        elif negative_count > 0 and positive_count == 0:
            sentiment_counts["negative"] += 1
        else:
            sentiment_counts["neutral"] += 1

    return sentiment_counts

def calculate_average_sleep_rating(reviews):
    mattress_ratings = {}
    for review in reviews:
        mattress_name = review['mattress_name']
        rating = review['rating']
        if mattress_name in mattress_ratings:
            mattress_ratings[mattress_name].append(rating)
        else:
            mattress_ratings[mattress_name] = [rating]

    average_ratings = {}
    for mattress_name, ratings in mattress_ratings.items():
        average_rating = sum(ratings) / len(ratings)
        average_ratings[mattress_name] = average_rating

    return average_ratings

