def most_frequent_play(plays):
    if not plays:
        return ""

    play_counts = {}

    for play in plays:
        if play in play_counts:
            play_counts[play] += 1
        else:
            play_counts[play] = 1

    max_count = max(play_counts.values())
    most_frequent_plays = [play for play, count in play_counts.items() if count == max_count]

    return sorted(most_frequent_plays)[0]

