def anonymize_patient_records(patient_records):
    def mask_name(name):
        names = name.split()
        masked_names = []
        for n in names:
            if len(n) > 1:
                masked_names.append(n[0] + '*' * (len(n) - 1))
            else:
                masked_names.append(n)
        return ' '.join(masked_names)

    def mask_phone_number(phone_number):
        phone_number = phone_number.replace('-', '')
        if len(phone_number) == 10:
            return phone_number[:3] + '-***-' + phone_number[7:]
        else:
            return phone_number

    anonymized_records = []
    for record in patient_records:
        anonymized_record = record.copy()
        anonymized_record['name'] = mask_name(record['name'])
        anonymized_record['phone_number'] = mask_phone_number(record['phone_number'])
        anonymized_records.append(anonymized_record)

    return anonymized_records

