def calculate_moving_average(stock_prices, window_size):
    if not stock_prices or window_size <= 0:
        return []

    moving_averages = []
    for i in range(len(stock_prices) - window_size + 1):
        window = stock_prices[i:i+window_size]
        average = sum(window) / len(window)
        moving_averages.append(average)

    return moving_averages

def analyze_tracks(tracks):
    artist_durations = {}
    total_duration = 0

    for track in tracks:
        artist = track['artist']
        duration = track['duration']
        total_duration += duration

        if artist in artist_durations:
            artist_durations[artist] += duration
        else:
            artist_durations[artist] = duration

    result = [{'artist': artist, 'total_duration': duration} for artist, duration in artist_durations.items()]
    return result

