def analyze_historical_events(events):
    monarch_counts = {}

    # Count occurrences of each monarch's name
    for event in events:
        monarch = extract_monarch_name(event)
        if monarch in monarch_counts:
            monarch_counts[monarch] += 1
        else:
            monarch_counts[monarch] = 1

    # Find the monarch with the highest count
    most_frequent_monarch = max(monarch_counts, key=monarch_counts.get)

    return most_frequent_monarch

